-- 329: Redesign the Custom Course Development landing page (coursedev_landing,
--      /course-development-service.html) to the franchise-style layout
--      (hero + visual timeline + supporting sections), matching
--      /franchising-application.html. Lead form is unchanged.
--
-- SG-only: gated on the SG marker category 'course-development-service'.
-- Hex-encoded (UNHEX), pure ASCII, idempotent. Flush Redis after deploy.

SET @sg := (SELECT COUNT(*) FROM catalog_category_entity_varchar cev JOIN eav_attribute ea ON ea.attribute_id=cev.attribute_id AND ea.entity_type_id=3 AND ea.attribute_code='url_key' WHERE cev.store_id=0 AND cev.value='course-development-service');

UPDATE cms_block SET content=UNHEX(''), update_time=NOW() WHERE identifier='coursedev_landing' AND @sg>0;
